const cfg=window.AFRIRISE_CONFIG;let token=null,factorId=null,resource='campaigns',offset=0,role=null;
const actions={save_campaign:{slug:'founding-fund',title:'AfriRise founding fund',goal_cents:50000000,currency:'USD',status:'draft',accepting_donations:false,activities:'',beneficiaries:'',location:'',eligibility:'',selection_process:'',budget:'',timeline:'',underfunding:'',excess_funds:'',delivery_impossible:'',update_schedule:'',refunds:'',cancellation:'',privacy:'',safeguarding:'',complaints:'',support_email:'',terms_version:'draft-1'},submit_expense:{campaign_id:'',description:'',amount_cents:0},approve_expense:{id:''},record_reconciliation:{payment_id:'',bank_reference:'',bank_received_cents:0,note:''},record_refund:{payment_id:'',refunded_cents:0,provider_refund_reference:''},save_milestone:{campaign_id:'',title:'',description:'',due_date:'',outcome:''},submit_content:{campaign_id:'',title:'',body:'',consent_reference:''},approve_content:{id:''}};
const resources={owner:['campaigns','donation_intents','payments','receipts','expenses','reconciliations','milestones','content_submissions','audit_log','support_requests','webhook_events'],finance:['campaigns','donation_intents','payments','receipts','expenses','reconciliations','audit_log','support_requests','webhook_events'],editor:['campaigns','milestones','content_submissions']};
const allowed={owner:Object.keys(actions),finance:['submit_expense','approve_expense','record_reconciliation','record_refund'],editor:['save_campaign','save_milestone','submit_content']};
const status=document.querySelector('#admin-status');
async function auth(path,method='GET',body){const r=await fetch(cfg.supabaseUrl+'/auth/v1/'+path,{method,headers:{apikey:cfg.supabaseAnonKey,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw new Error(data.msg||data.message||data.error_description||'Authentication failed.');return data}
async function api(path,body){const r=await fetch(cfg.apiBase+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed');return d}
if(cfg.apiBase&&cfg.supabaseUrl&&cfg.supabaseAnonKey){document.querySelector('#login-button').disabled=false;status.textContent='Staff sign-in requires an assigned role and authenticator verification.'}
document.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();try{const result=await auth('token?grant_type=password','POST',{email:document.querySelector('#admin-email').value,password:document.querySelector('#admin-password').value});token=result.access_token;document.querySelector('#admin-password').value='';document.querySelector('#login-form').hidden=true;document.querySelector('#logout').hidden=false;const factors=await auth('factors');const list=Array.isArray(factors)?factors:(factors.all||factors.totp||[]);const verified=list.find(x=>x.factor_type==='totp'&&x.status==='verified');document.querySelector('#mfa-panel').hidden=false;if(verified){factorId=verified.id;document.querySelector('#mfa-info').textContent='Enter the code from your authenticator app.'}else{const created=await auth('factors','POST',{factor_type:'totp',friendly_name:'AfriRise staff'});factorId=created.id;document.querySelector('#mfa-info').textContent='Add this setup secret to your authenticator: '+created.totp.secret;status.textContent='Finish MFA enrolment to access operational records.'}}catch(e){status.textContent=e.message}});
document.querySelector('#mfa-form').addEventListener('submit',async e=>{e.preventDefault();try{const challenge=await auth(`factors/${factorId}/challenge`,'POST',{});const verified=await auth(`factors/${factorId}/verify`,'POST',{challenge_id:challenge.id,code:document.querySelector('#mfa-code').value});token=verified.access_token;document.querySelector('#mfa-code').value='';document.querySelector('#mfa-info').textContent='';const session=await api('/admin/session');role=session.role;document.querySelector('#login-panel').hidden=true;document.querySelector('#admin-workspace').hidden=false;status.textContent='Signed in · '+role+' · MFA verified';const nav=document.querySelector('#admin-nav');nav.replaceChildren();for(const name of resources[role]){const b=document.createElement('button');b.textContent=name.replaceAll('_',' ');b.addEventListener('click',()=>{resource=name;offset=0;loadRecords()});nav.append(b)}const select=document.querySelector('#admin-action');select.replaceChildren();for(const action of allowed[role]){const o=document.createElement('option');o.value=action;o.textContent=action.replaceAll('_',' ');select.append(o)}setTemplate();loadRecords()}catch(e){status.textContent=e.message}});
function setTemplate(){document.querySelector('#action-data').value=JSON.stringify(actions[document.querySelector('#admin-action').value],null,2)}document.querySelector('#admin-action').addEventListener('change',setTemplate);
async function loadRecords(){try{const rows=await api('/admin/records?resource='+resource+'&offset='+offset);const columns=rows.length?Object.keys(rows[0]):[];document.querySelector('#records-head').replaceChildren();document.querySelector('#records-body').replaceChildren();const tr=document.createElement('tr');for(const key of columns){const th=document.createElement('th');th.textContent=key;tr.append(th)}document.querySelector('#records-head').append(tr);for(const row of rows){const tr=document.createElement('tr');for(const key of columns){const td=document.createElement('td');td.textContent=typeof row[key]==='object'?JSON.stringify(row[key]):String(row[key]??'');tr.append(td)}document.querySelector('#records-body').append(tr)}if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.textContent='No records on this page.';tr.append(td);document.querySelector('#records-body').append(tr)}document.querySelector('#previous-page').disabled=offset===0;document.querySelector('#next-page').disabled=rows.length<100;[...document.querySelector('#admin-nav').children].forEach(b=>b.classList.toggle('active',b.textContent===resource.replaceAll('_',' ')))}catch(e){status.textContent=e.message}}
document.querySelector('#save-action').addEventListener('click',async()=>{const output=document.querySelector('#action-feedback');try{const data=JSON.parse(document.querySelector('#action-data').value);await api('/admin/action',{action:document.querySelector('#admin-action').value,data});output.textContent='Saved with an audit record.';loadRecords()}catch(e){output.textContent=e.message}});
document.querySelector('#previous-page').addEventListener('click',()=>{offset=Math.max(0,offset-100);loadRecords()});document.querySelector('#next-page').addEventListener('click',()=>{offset+=100;loadRecords()});document.querySelector('#logout').addEventListener('click',async()=>{try{await auth('logout','POST',{})}catch{}token=null;location.reload()});
